const body = $json.body || $json;
const headers = $json.headers || {};
const eventType = String(body.eventType || '').trim();
const payload = body.payload || {};

const expectedSecret = String($env.LIFT_AUTOMATION_SECRET || '').trim();
const incomingSecret = String(headers['x-lift-automation-secret'] || headers['X-Lift-Automation-Secret'] || '').trim();
if (expectedSecret && incomingSecret && expectedSecret !== incomingSecret) {
  return [{
    json: {
      eventType: 'invalid_secret',
      email: '',
      whatsappTo: '',
      emailSubject: '',
      emailText: '',
      whatsAppText: ''
    }
  }];
}

let email = '';
let whatsappTo = '';
let emailSubject = '';
let emailText = '';
let whatsAppText = '';

if (eventType === 'onboarding.new_institution') {
  const institution = payload.institution || {};
  const admin = payload.admin || {};
  email = String(admin.email || '').trim();
  whatsappTo = String(admin.phone || '').trim();
  emailSubject = `Welcome to LIFT - ${institution.name || 'Institution'}`;
  emailText = `Hi ${admin.fullName || 'Admin'},\n\nYour institution is now ready on LIFT.\nInstitution ID: ${institution.institutionId || ''}\nUsername: ${admin.username || ''}\nTemporary Password: ${admin.temporaryPassword || ''}\n\nPlease log in and change password immediately.`;
  whatsAppText = `Welcome to LIFT. Institution ID: ${institution.institutionId || ''}, Username: ${admin.username || ''}, Temp Password: ${admin.temporaryPassword || ''}`;
}

if (eventType === 'onboarding.new_teacher') {
  const teacher = payload.teacher || {};
  email = String(teacher.email || '').trim();
  whatsappTo = String(teacher.phone || '').trim();
  emailSubject = `Your LIFT Teacher Account`;
  emailText = `Hi ${teacher.fullName || 'Teacher'},\n\nYour teacher account is created.\nUsername: ${teacher.username || ''}\nTemporary Password: ${teacher.temporaryPassword || ''}\n\nPlease sign in and change your password.`;
  whatsAppText = `LIFT Teacher account created. Username: ${teacher.username || ''}, Temp Password: ${teacher.temporaryPassword || ''}`;
}

if (eventType === 'onboarding.new_student') {
  const student = payload.student || {};
  email = String(student.email || '').trim();
  whatsappTo = String(student.phone || '').trim();
  emailSubject = `Your LIFT Student Account`;
  emailText = `Hi ${student.fullName || 'Student'},\n\nYour student account is ready.\nUsername: ${student.username || ''}\nTemporary Password: ${student.temporaryPassword || ''}\n\nUse first-time password setup after login.`;
  whatsAppText = `LIFT Student account ready. Username: ${student.username || ''}, Temp Password: ${student.temporaryPassword || ''}`;
}

return [{
  json: {
    eventType,
    email,
    whatsappTo,
    emailSubject,
    emailText,
    whatsAppText
  }
}];
